SELECT "o_orderpriority", CASE WHEN (COUNT(*) FILTER (WHERE "o_orderstatus" = 'O')) = 0 THEN NULL ELSE COALESCE(SUM("o_totalprice") FILTER (WHERE "o_orderstatus" = 'O'), 0) END AS "unfilled_total", COUNT(*) FILTER (WHERE "o_orderstatus" = 'O') AS "unfilled_n", CASE WHEN (COUNT(*) FILTER (WHERE "o_orderstatus" = 'F')) = 0 THEN NULL ELSE COALESCE(SUM("o_totalprice") FILTER (WHERE "o_orderstatus" = 'F'), 0) END AS "filled_total", COUNT(*) FILTER (WHERE "o_orderstatus" = 'F') AS "filled_n", CASE WHEN (COUNT(*) FILTER (WHERE "o_orderstatus" = 'P')) = 0 THEN NULL ELSE COALESCE(SUM("o_totalprice") FILTER (WHERE "o_orderstatus" = 'P'), 0) END AS "pending_total", COUNT(*) FILTER (WHERE "o_orderstatus" = 'P') AS "pending_n" FROM "orders" GROUP BY "o_orderpriority" ORDER BY "o_orderpriority"
